import type {Message, MessageChunk, ToolCall, UsageMetadata} from '../types/ai.js';
import type {ToolRegistry} from './tools/registry.js';

export function shouldContinueToolLoop(
  stopReason: string,
  pendingToolCalls: ToolCall[],
  toolRegistry: ToolRegistry | undefined
): boolean {
  return stopReason === 'tool_use' && pendingToolCalls.length > 0 && toolRegistry !== undefined;
}

export async function collectText(stream: AsyncGenerator<MessageChunk>): Promise<string> {
  let text = '';
  for await (const chunk of stream) {
    if (chunk.type === 'text') text += chunk.text;
  }
  return text;
}

export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
  return {
    role: 'assistant',
    content: pendingToolCalls.map(tc => ({
      type: 'tool_use' as const,
      toolUseId: tc.id,
      name: tc.name,
      input: tc.input,
    })),
  };
}

export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
}

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}
  return true;
}

// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
async function* closeExhaustedTurn(
  session: ChatSession,
  budget: ToolBudgetInfo,
  hook?: OnToolBudgetExhausted
): AsyncGenerator<MessageChunk, string> {
  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
  if (sentence !== '') yield {type: 'text', text: sentence};
  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
  return sentence;
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

